# bash completion for xavani (generated by scripts/gen_completions.py)
_xavani_completions() {
    local cur prev
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"
    local base="${cur%% *}"
    local words="'/agents' '/background' '/bg' '/branch' '/browser' '/browser connect' '/browser disconnect' '/browser status' '/btw' '/bundles' '/busy' '/busy interrupt' '/busy queue' '/busy status' '/busy steer' '/clear' '/cm' '/codex-runtime' '/codex_runtime' '/compress' '/config' '/copy' '/cost' '/cron' '/cron add' '/cron create' '/cron edit' '/cron list' '/cron pause' '/cron remove' '/cron resume' '/cron run' '/curator' '/curator list-archived' '/curator pause' '/curator pin' '/curator restore' '/curator resume' '/curator run' '/curator status' '/curator unpin' '/debug' '/exit' '/fast' '/fast fast' '/fast normal' '/fast off' '/fast on' '/fast status' '/footer' '/footer off' '/footer on' '/footer status' '/fork' '/g' '/gateway' '/goal' '/gquota' '/guidelines' '/guidelines check' '/guidelines list' '/guidelines show' '/handoff' '/help' '/history' '/image' '/indicator' '/indicator ascii' '/indicator emoji' '/indicator kaomoji' '/indicator unicode' '/insights' '/kanban' '/kanban archive' '/kanban assign' '/kanban assignees' '/kanban block' '/kanban boards' '/kanban claim' '/kanban comment' '/kanban complete' '/kanban context' '/kanban create' '/kanban diag' '/kanban diagnostics' '/kanban dispatch' '/kanban edit' '/kanban gc' '/kanban heartbeat' '/kanban init' '/kanban link' '/kanban list' '/kanban log' '/kanban ls' '/kanban notify-list' '/kanban notify-subscribe' '/kanban notify-unsubscribe' '/kanban reassign' '/kanban reclaim' '/kanban runs' '/kanban show' '/kanban specify' '/kanban stats' '/kanban tail' '/kanban unblock' '/kanban unlink' '/ls' '/memory' '/memory approval' '/memory approve' '/memory pending' '/memory reject' '/model' '/new' '/paste' '/personality' '/platforms' '/plugins' '/profile' '/provider' '/q' '/queue' '/quit' '/r' '/reasoning' '/reasoning hide' '/reasoning high' '/reasoning low' '/reasoning medium' '/reasoning minimal' '/reasoning none' '/reasoning off' '/reasoning on' '/reasoning show' '/reasoning xhigh' '/redraw' '/reload' '/reload-mcp' '/reload-skills' '/reload_mcp' '/reload_skills' '/reset' '/resume' '/retry' '/rollback' '/save' '/sb' '/sessions' '/skills' '/skills approval' '/skills approve' '/skills browse' '/skills diff' '/skills inspect' '/skills install' '/skills pending' '/skills reject' '/skills search' '/skin' '/snap' '/snapshot' '/st' '/stash' '/stash list' '/stash load' '/stash rm' '/stash show' '/status' '/statusbar' '/steer' '/stop' '/subgoal' '/tasks' '/title' '/tools' '/toolsets' '/undo' '/update' '/usage' '/verbose' '/voice' '/voice off' '/voice on' '/voice status' '/voice tts' '/who' '/whoami' '/yolo'"
    if [[ "$cur" == *" "* ]]; then
        local candidates
        candidates=$(printf '%s\n' $words | grep -F -- "${base} " | sed "s/^${base} //")
        COMPREPLY=( $(compgen -W "$candidates" -- "${cur##* }") )
    else
        COMPREPLY=( $(compgen -W "$words" -- "$cur") )
    fi
}
complete -F _xavani_completions xavani
